package entities

type (
	File struct {
		Mp3128 string `json:"mp3-128"`
	}

	TrackInfo struct {
		File      File    `json:"file"`
		TrackNum  int     `json:"track_num"`
		TrackID   int     `json:"track_id"`
		Title     string  `json:"title"`
		TitleLink string  `json:"title_link"`
		Duration  float64 `json:"duration"`
		HasLyrics bool    `json:"has_lyrics"`
		Lyrics    string  `json:"lyrics"`
	}

	Current struct {
		ReleaseDate string `json:"release_date"`
		Artist      any    `json:"artist"`
		Title       string `json:"title"`
		ID          int64  `json:"id"`
		ArtID       int    `json:"art_id"`
	}

	TrackData struct {
		Current              Current     `json:"current"`
		TrackInfo            []TrackInfo `json:"trackinfo"`
		ItemType             string      `json:"item_type"`
		Artist               string      `json:"artist"`
		About                string      `json:"about"`
		AlbumReleaseDate     string      `json:"album_release_date"`
		ArtID                int         `json:"art_id"`
		BasePath             string
		ArtworkURL           string
		AlbumArtworkFilepath string
		CurrentTrackTitle    string
		CurrentTrackURL      string
		CurrentTrackFilepath string
		CurrentTrackNum      string
	}

	FanData struct {
		FanId int `json:"fan_id"`
	}

	CollectionData struct {
		FanData          FanData           `json:"fan_data"`
		RedownloadURLs   map[string]string `json:"redownload_urls"`
		LastToken        string            `json:"last_token"`
		ItemCount        int               `json:"item_count"`
		BatchSize        int               `json:"batch_size"`
		HiddenItemsCount int               `json:"hidden_items_count"`
		SmallCollection  bool              `json:"small_collection"`
		SmallWishlist    bool              `json:"small_wishlist"`
		PurchaseInfos    map[string]any    `json:"purchase_infos"`
		Collectors       map[string]any    `json:"collectors"`
		Sequence         []string          `json:"sequence"`
		PendingSequence  []string          `json:"pending_sequence"`
	}

	CollectionItemData struct {
		ID     int    `json:"item_id"`
		Title  string `json:"item_title"`
		ArtURL string `json:"item_art_url"`
		URL    string `json:"item_url"`
	}

	CollectionItemsData struct {
		LastToken      string               `json:"last_token"`
		RedownloadURLs map[int]string       `json:"redownload_urls"`
		Items          []CollectionItemData `json:"items"`
	}

	WishlistData struct {
		LastToken       string   `json:"last_token"`
		ItemCount       int      `json:"item_count"`
		BatchSize       int      `json:"batch_size"`
		Hidden          bool     `json:"hidden"`
		Sequence        []string `json:"sequence"`
		PendingSequence []string `json:"pending_sequence"`
	}
)

